PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE policiais (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nome TEXT NOT NULL,
    matricula TEXT NOT NULL UNIQUE,
    cargo TEXT NOT NULL CHECK(cargo IN ('DPC', 'OIP')),
    telefone TEXT,
    lotacao TEXT NOT NULL,
    ativo INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, senha TEXT NOT NULL DEFAULT 'ef797c8118f02dfb649607dd5d3f8c7623048c9c063d532cc95c5ed7a898a64f', primeiro_acesso INTEGER NOT NULL DEFAULT 1, regime TEXT CHECK(regime IN ('plantao', 'expediente', 'ambos')) NOT NULL DEFAULT 'ambos', classe TEXT NOT NULL DEFAULT '', papel TEXT CHECK(papel IN ('admin_seccional', 'admin_unidade')), papel_unidade_id INTEGER REFERENCES unidades(id) ON DELETE SET NULL, cpf TEXT, email TEXT, email_pessoal TEXT, email_pessoal_verificado INTEGER NOT NULL DEFAULT 0);
CREATE TABLE escalas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    titulo TEXT NOT NULL,
    cidade TEXT NOT NULL,
    data_inicio TEXT NOT NULL,
    data_fim TEXT NOT NULL,
    horario TEXT NOT NULL DEFAULT '08H A 08H',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
, hora_entrada TEXT NOT NULL DEFAULT '08', hora_saida TEXT NOT NULL DEFAULT '08', lotacao TEXT NOT NULL DEFAULT '', tipo TEXT CHECK(tipo IN ('plantao', 'expediente', 'fds')), visto_por_admin INTEGER NOT NULL DEFAULT 0, finalizada_em TEXT, email_envio TEXT);
CREATE TABLE escala_policiais (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    escala_id INTEGER NOT NULL,
    policial_id INTEGER NOT NULL,
    data_plantao TEXT NOT NULL, horario TEXT NOT NULL DEFAULT '', hora_entrada TEXT NOT NULL DEFAULT '', hora_saida TEXT NOT NULL DEFAULT '', data_saida TEXT NOT NULL DEFAULT '', observacoes TEXT NOT NULL DEFAULT '', equipe TEXT NOT NULL DEFAULT '',
    FOREIGN KEY (escala_id) REFERENCES escalas(id) ON DELETE CASCADE,
    FOREIGN KEY (policial_id) REFERENCES policiais(id) ON DELETE CASCADE
);
CREATE TABLE administradores (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    login TEXT NOT NULL UNIQUE,
    senha TEXT NOT NULL,
    nome TEXT NOT NULL,
    primeiro_acesso INTEGER NOT NULL DEFAULT 1,
    created_at TEXT DEFAULT (datetime('now'))
, email TEXT, email_pessoal TEXT, email_pessoal_verificado INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessoes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    token TEXT NOT NULL UNIQUE,
    tipo TEXT NOT NULL CHECK(tipo IN ('policial', 'admin')),
    usuario_id INTEGER NOT NULL,
    created_at TEXT DEFAULT (datetime('now')),
    expires_at TEXT NOT NULL
);
CREATE TABLE unidades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nome TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
, `tem_plantao` integer DEFAULT false NOT NULL, `tem_expediente` integer DEFAULT false NOT NULL, `tem_fds` integer DEFAULT false NOT NULL, `tipo` text DEFAULT 'delegacia' NOT NULL, `seccional_id` integer, cidade TEXT NOT NULL DEFAULT '');
CREATE TABLE `escala_documentos` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`escala_id` integer NOT NULL,
	`r2_key` text NOT NULL,
	`assinante_nome` text NOT NULL,
	`assinante_cpf` text,
	`created_at` text DEFAULT (datetime('now')), verificacao_hash TEXT, ip_address TEXT, user_agent TEXT, latitude REAL, longitude REAL, selfie_key text, arquivo_hash text, assinante_email TEXT, tipo_carimbo_tempo TEXT DEFAULT 'servidor',
	FOREIGN KEY (`escala_id`) REFERENCES `escalas`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE gise_modelo_formulario (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    config TEXT NOT NULL, -- JSON com a estrutura das perguntas
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, tipo TEXT NOT NULL DEFAULT 'operacional');
CREATE TABLE login_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ip TEXT NOT NULL,
    attempted_at TEXT NOT NULL DEFAULT (datetime('now')),
    success INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE configuracoes (
    chave TEXT PRIMARY KEY,
    valor TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT (datetime('now', '-3 hours'))
);
CREATE TABLE audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    usuario_id INTEGER,
    usuario_nome TEXT NOT NULL DEFAULT '',
    usuario_papel TEXT,
    acao TEXT NOT NULL,
    entidade TEXT NOT NULL,
    entidade_id INTEGER,
    detalhes TEXT,
    ip TEXT,
    user_agent TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE reset_senha_tokens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    token TEXT NOT NULL UNIQUE,
    tipo_usuario TEXT NOT NULL CHECK(tipo_usuario IN ('policial', 'admin')),
    usuario_id INTEGER NOT NULL,
    expires_at TEXT NOT NULL,
    usado INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now', '-3 hours'))
);
CREATE TABLE IF NOT EXISTS "gise_seccional_unidades" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gise_seccional_id INTEGER NOT NULL REFERENCES gise_seccionais(id) ON DELETE CASCADE,
  unidade_id INTEGER REFERENCES unidades(id) ON DELETE SET NULL
);
CREATE TABLE gise_seccionais (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gise_id INTEGER NOT NULL REFERENCES gise_escalas(id) ON DELETE CASCADE,
  seccional_id INTEGER NOT NULL REFERENCES unidades(id),
  unidade_operacional_id INTEGER,
  status TEXT NOT NULL DEFAULT 'pendente'
    CHECK(status IN ('pendente','preenchida','retificada','preenchida_retificada')),
  hora_entrada TEXT,
  hora_saida TEXT,
  UNIQUE(gise_id, seccional_id)
);
CREATE TABLE gise_membros (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  equipe_id INTEGER NOT NULL REFERENCES gise_equipes(id) ON DELETE CASCADE,
  policial_id INTEGER NOT NULL REFERENCES policiais(id) ON DELETE CASCADE
);
CREATE TABLE gise_documentos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gise_id INTEGER NOT NULL REFERENCES gise_escalas(id) ON DELETE CASCADE,
  r2_key TEXT NOT NULL,
  assinante_id INTEGER,
  assinante_nome TEXT NOT NULL DEFAULT '',
  assinante_cpf TEXT NOT NULL DEFAULT '',
  verificacao_hash TEXT UNIQUE,
  selfie_key TEXT,
  arquivo_hash TEXT,
  rubrica TEXT,
  ip_address TEXT,
  user_agent TEXT,
  latitude REAL,
  longitude REAL,
  created_at TEXT DEFAULT (datetime('now')), assinante_email TEXT, tipo_carimbo_tempo TEXT DEFAULT 'servidor',
  UNIQUE(gise_id)
);
CREATE TABLE gise_presencas (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gise_id INTEGER NOT NULL REFERENCES gise_escalas(id) ON DELETE CASCADE,
  policial_id INTEGER NOT NULL REFERENCES policiais(id) ON DELETE CASCADE,
  entrada_timestamp TEXT,
  entrada_rubrica TEXT,
  saida_timestamp TEXT,
  saida_rubrica TEXT,
  ip_address TEXT,
  user_agent TEXT,
  latitude REAL,
  longitude REAL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')), entrada_selfie_key TEXT, saida_selfie_key TEXT,
  UNIQUE(gise_id, policial_id)
);
CREATE TABLE gise_respostas_formulario (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gise_id INTEGER NOT NULL REFERENCES gise_escalas(id) ON DELETE CASCADE,
  policial_id INTEGER NOT NULL REFERENCES policiais(id) ON DELETE CASCADE,
  equipe_id INTEGER REFERENCES gise_equipes(id) ON DELETE CASCADE,
  respostas TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(gise_id, policial_id)
);
CREATE TABLE gise_assinaturas_relatorios (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gise_id INTEGER NOT NULL REFERENCES gise_escalas(id) ON DELETE CASCADE,
  seccional_id INTEGER NOT NULL REFERENCES unidades(id) ON DELETE CASCADE,
  tipo TEXT NOT NULL CHECK(tipo IN ('extraordinario','produtividade')),
  assinante_id INTEGER,
  assinante_nome TEXT NOT NULL,
  assinante_cpf TEXT,
  tipo_assinatura TEXT NOT NULL CHECK(tipo_assinatura IN ('simples','webpki','serpro')),
  rubrica TEXT,
  selfie_key TEXT,
  arquivo_hash TEXT,
  verification_hash TEXT UNIQUE,
  ip_address TEXT,
  user_agent TEXT,
  latitude REAL,
  longitude REAL,
  created_at TEXT DEFAULT (datetime('now')), r2_key TEXT, assinante_email TEXT, tipo_carimbo_tempo TEXT DEFAULT 'servidor',
  UNIQUE(gise_id, seccional_id, tipo)
);
CREATE TABLE IF NOT EXISTS "gise_escalas" (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  data_inicio  TEXT    NOT NULL,
  hora_entrada TEXT    NOT NULL DEFAULT '08:00',
  hora_saida   TEXT    NOT NULL DEFAULT '16:00',
  status       TEXT    NOT NULL DEFAULT 'em_definicao_supervisor'
               CHECK (status IN (
                 'em_definicao_supervisor',
                 'em_preenchimento',
                 'aguardando_assinatura',
                 'em_andamento',
                 'aguardando_relatorios',
                 'aguardando_assinatura_relat',
                 'pronta_para_finalizar',
                 'finalizada'
               )),
  supervisor_id INTEGER,
  created_at   TEXT    NOT NULL DEFAULT (datetime('now'))
, `assessor_id` integer, `seint1_id` integer, `seint2_id` integer, `feriado` integer DEFAULT 0 NOT NULL, breve_relatorio_titulo TEXT, breve_relatorio_texto_seccional TEXT, breve_relatorio_texto_supervisao TEXT, planilha_base_equipe_alimentada_em TEXT, assessor_email_notificacao TEXT);
CREATE TABLE IF NOT EXISTS "gise_equipes" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gise_seccional_id INTEGER NOT NULL REFERENCES gise_seccionais(id) ON DELETE CASCADE,
  tipo TEXT NOT NULL CHECK(tipo IN ('operacional','seint')),
  slots_dpc INTEGER NOT NULL DEFAULT 0,
  slots_oip INTEGER NOT NULL DEFAULT 0,
  hora_entrada TEXT,
  hora_saida TEXT
, gise_unidade_id INTEGER REFERENCES gise_seccional_unidades(id) ON DELETE CASCADE);
CREATE TABLE dois_fatores_tokens (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	desafio_id TEXT NOT NULL UNIQUE,
	tipo TEXT NOT NULL CHECK(tipo IN ('policial', 'admin', 'assinatura', 'reset_policial', 'reset_admin')),
	usuario_id INTEGER NOT NULL,
	codigo TEXT NOT NULL,
	tentativas INTEGER NOT NULL DEFAULT 0,
	expires_at TEXT NOT NULL,
	usado INTEGER NOT NULL DEFAULT 0,
	created_at TEXT NOT NULL DEFAULT (datetime('now', '-3 hours'))
);
DELETE FROM sqlite_sequence;
